cat > s4.mjs <<'EOF'
import { chromium } from 'playwright';
import fs from 'fs';
const b = await chromium.launch({headless:true});
const p = await b.newPage();
await p.goto('http://127.0.0.1:54569');
await p.fill('#email','ops@lab.test');
await p.fill('#password','lab-ops-pass');
await p.click('button[type=submit]');
await p.waitForTimeout(800);
await p.goto('http://127.0.0.1:54569/integrations');
await p.waitForTimeout(500);
await p.click('#gen');
await p.waitForFunction(() => !document.getElementById('toast').hidden);
const txt = await p.textContent('#toast');
console.log('TOAST:', txt);
const key = txt.split(': ').slice(1).join(': ').trim();
fs.writeFileSync('key.txt', key);
await p.goto('http://127.0.0.1:54569/webhooks');
await p.waitForTimeout(800);
console.log(await p.content());
await b.close();
EOF
node s4.mjs | sed -n '/TOAST/p;/<main/,$p'; cat key.txt

cat > s5.mjs <<'EOF'
import { chromium } from 'playwright';
import fs from 'fs';
const key = fs.readFileSync('key.txt','utf8').trim();
const b = await chromium.launch({headless:true});
const p = await b.newPage();
await p.goto('http://127.0.0.1:54569');
await p.fill('#email','ops@lab.test');
await p.fill('#password','lab-ops-pass');
await p.click('button[type=submit]');
await p.waitForTimeout(800);
await p.goto('http://127.0.0.1:54569/webhooks');
await p.waitForTimeout(500);
await p.fill('#secret', key);
await p.click('#save');
await p.waitForTimeout(800);
console.log('done:', await p.textContent('#done'), '| value:', await p.inputValue('#secret'));
await b.close();
EOF
node s5.mjs
